#include <vector>

std::vector<int> interleave_vectors(const std::vector<int>& vec1, const std::vector<int>& vec2) {
    std::vector<int> result;
    size_t size = std::max(vec1.size(), vec2.size());
    for (size_t i = 0; i < size; i++) {
        if (i < vec1.size()) result.push_back(vec1[i]);
        if (i < vec2.size()) result.push_back(vec2[i]);
    }
    return result;
}

int main() {
    std::vector<int> vec1 = {1, 3, 5};
    std::vector<int> vec2 = {2, 4, 6};
    std::vector<int> interleaved = interleave_vectors(vec1, vec2);
    for (int num : interleaved) std::cout << num << " ";
    return 0;
}
