{
    Integer i1(3);

    cout << "Before increment: ";
    i1.display();

    // Using the pre-increment operator
    Integer i2 = ++i1;

    cout << "After pre increment: " << endl;
    cout << "i1: ";
    i1.display();
    cout << "i2: ";  
    i2.display();
}
