    // Initialize the matrix
    let matrix: [[i32; 4]; 4] = [
        [1, 0, 2, -1],
        [3, 0, 0, 5],
        [2, 1, 4, -3],
        [1, 0, 5, 0],
    ];

    let n = 4;
    let det = determinant(&matrix, n);

    println!("Determinant: {}", det);
}
