use std::sync::{Arc, Mutex, OnceLock};

// Define a thread-safe Singleton struct
#[derive(Debug)]
struct Singleton {
    name: String,
    loves: String,
}

// Implement methods for Singleton
impl Singleton {
    // Private constructor (enforced via Singleton pattern)
    fn new() -> Self {
        Self {
            name: String::new(),
            loves: String::new(),
        }
    }

    // Set values for Singleton instance
    fn set_values(&mut self, name: &str, loves: &str) {
        self.name = name.to_string();
        self.loves = loves.to_string();
    }

    // Print values
    fn print(&self) {
        println!("{} Loves {}.", self.name, self.loves);
    }
}

// Thread-safe Singleton implementation
struct SingletonManager;

impl SingletonManager {
    // Static instance stored using OnceLock (lazy, thread-safe initialization)
    fn get_instance() -> Arc<Mutex<Singleton>> {
        static INSTANCE: OnceLock<Arc<Mutex<Singleton>>> = OnceLock::new();
        INSTANCE.get_or_init(|| Arc::new(Mutex::new(Singleton::new()))).clone()
    }
}

// Driver function
fn main() {
    let singleton1 = SingletonManager::get_instance();
    {
        let mut s1 = singleton1.lock().unwrap();
        s1.set_values("Manish", "Tea");
        s1.print();
    }

    let singleton2 = SingletonManager::get_instance();
    {
        let mut s2 = singleton2.lock().unwrap();
        s2.set_values("Vartika", "Tea");
        s2.print();
    }

    // Proving that both instances are the same
    println!(
        "Are s1 and s2 the same instance? {}",
        Arc::ptr_eq(&singleton1, &singleton2)
    );
}
