bool is_smith_number(int num) {
    auto sum_of_digits = [](int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    };

    int sum_digits = sum_of_digits(num);
    int sum_prime_factors = 0, temp = num;

    for (int i = 2; i * i <= temp; i++) {
        while (temp % i == 0) {
            sum_prime_factors += sum_of_digits(i);
            temp /= i;
        }
    }
    if (temp > 1) sum_prime_factors += sum_of_digits(temp);

    return sum_digits == sum_prime_factors;
}

int main() {
    std::cout << "Is 666 a Smith number? " << is_smith_number(666) << std::endl;
    return 0;
}
