use std::collections::BinaryHeap;
use std::cmp::Ordering;

#[derive(Eq, PartialEq)]
struct State {
    cost: usize,
    position: usize,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn dijkstra(start: usize, graph: &Vec<Vec<(usize, usize)>>) -> Vec<usize> {
    let inf = usize::MAX;
    let mut dist = vec![inf; graph.len()];
    dist[start] = 0;

    let mut heap = BinaryHeap::new();
    heap.push(State { cost: 0, position: start });

    while let Some(State { cost, position }) = heap.pop() {
        if cost > dist[position] { continue; }

        for &(neighbor, weight) in &graph[position] {
            let next = State { cost: cost + weight, position: neighbor };
            if next.cost < dist[neighbor] {
                dist[neighbor] = next.cost;
                heap.push(next);
            }
        }
    }

    dist
}

fn main() {
    let graph = vec![
        vec![(1, 4), (2, 1)],
        vec![(2, 2), (3, 5)],
        vec![(3, 1)],
        vec![],
    ];

    let result = dijkstra(0, &graph);
    println!("{:?}", result);
}
