use std::fs::{File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Write};

fn main() -> io::Result<()> {
    // Open the source file for reading
    let source_file = File::open("file.txt")?;
    let mut reader = BufReader::new(source_file);

    // Open the destination file in append mode
    let dest_file = OpenOptions::new().append(true).create(true).open("file2.txt")?;
    let mut writer = BufWriter::new(dest_file);

    // Copy contents from source to destination
    let mut buffer = Vec::new();
    reader.read_to_end(&mut buffer)?;
    writer.write_all(&buffer)?;

    // Ensure all writes are flushed
    writer.flush()?;

    // Reopen file2.txt to read and display its contents
    let mut file2 = File::open("file2.txt")?;
    let mut content = String::new();
    file2.read_to_string(&mut content)?;

    // Print the content of file2.txt
    print!("{}", content);

    Ok(())
}
