fn binary_search(v: &[i32], target: i32) -> bool {
    let mut low = 0;
    let mut high = v.len() - 1;

    // While the search space is valid
    while low <= high {
        let mid = low + (high - low) / 2;

        // If the middle element is equal to the target
        if v[mid] == target {
            return true;
        }

        // If the middle element is greater than target, search the left half
        if v[mid] > target {
            high = mid - 1;
        }
        // If the middle element is smaller than target, search the right half
        else {
            low = mid + 1;
        }
    }

    // If target is not found
    false
}

