void decToOctal(int n) 
{ 
    // Array to store octal number 
    int octalNum[100]; 

    // Counter for octal number array 
    int i = 0; 
    while (n != 0) { 
        // Storing remainder in octal array 
        octalNum[i] = n % 8; 
        n = n / 8; 
        i++; 
    } 

    // Printing octal number array in 
    // reverse order 
    for (int j = i - 1; j >= 0; j--) 
