    std::vector<std::vector<int>> matrix(n, std::vector<int>(n));
    fill_spiral(matrix, n);
    for (const auto& row : matrix) {
        for (int num : row) std::cout << num << " ";
        std::cout << std::endl;
    }
    return 0;
