fn fill_spiral(n: usize) -> Vec<Vec<i32>> {
    let mut matrix = vec![vec![0; n]; n];
    let (mut val, mut left, mut right, mut top, mut bottom) = (1, 0, n - 1, 0, n - 1);
    while left <= right && top <= bottom {
        for i in left..=right { matrix[top][i] = val; val += 1; }
        top += 1;
        for i in top..=bottom { matrix[i][right] = val; val += 1; }
        if right > 0 { right -= 1; }
        for i in (left..=right).rev() { matrix[bottom][i] = val; val += 1; }
        if bottom > 0 { bottom -= 1; }
        for i in (top..=bottom).rev() { matrix[i][left] = val; val += 1; }
        left += 1;
    }
    matrix
}

