    if n < 2 {
        return false;
    }
    for i in 2..=((n as f64).sqrt() as i32) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn is_super_prime(num: i32) -> bool {
    if !is_prime(num) {
        return false;
    }

    let mut index = 1;
    let mut count = 0;
    for i in 2.. {
        if is_prime(i) {
            count += 1;
            if i == num {
                return is_prime(index);
            }
            index += 1;
        }
        if count > num {
