std::vector<int> rolling_average(const std::vector<int>& vec, int window_size) {
    std::vector<int> result;
    for (size_t i = 0; i + window_size <= vec.size(); i++) {
        int sum = 0;
        for (size_t j = 0; j < window_size; j++) {
            sum += vec[i + j];
        }
        result.push_back(sum / window_size);
    }
    return result;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5, 6};
    std::vector<int> averaged = rolling_average(vec, 3);
    for (int num : averaged) std::cout << num << " ";
    return 0;
}
```

