// Function to check if a string is a palindrome
fn is_palindrome(s: &str) {
    let mut left = 0;
    let mut right = s.len() - 1;

    // Iterate while left index is less than right index
    while left < right {
        // If characters at left and right don't match, it's not a palindrome
        if s.as_bytes()[left] != s.as_bytes()[right] {
            println!("\"{}\" is NOT palindrome.", s);
            return;
        }
        left += 1;
        right -= 1;
    }

    println!("\"{}\" is palindrome.", s);
}

fn main() {
    // Checking if given strings are palindrome
    is_palindrome("ABCDCBA");
    is_palindrome("ABCD");
}
```

