fn is_prime(n: i32) -> bool {
    if n < 2 {
        return false;
    }
    for i in 2..=((n as f64).sqrt() as i32) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn is_superprime(num: i32) -> bool {
    let mut index = 1;
    let mut count = 0;

    for i in 2.. {
        if is_prime(i) {
            count += 1;
            if count == num {
                return is_prime(index);
            }
            index += 1;
        }
        if count >= num {
            break;
        }
    }
    false
}

fn main() {
    println!("Is 11 a superprime? {}", is_superprime(11));
}
